<script setup>
import {Head,Link,useForm,usePage} from '@inertiajs/vue3';import {computed,ref} from 'vue';import TurnstileWidget from '../../Components/TurnstileWidget.vue';import CustomerShell from '../../Components/CustomerShell.vue';
const page=usePage(),turnstile=ref(null),security=computed(()=>page.props.security||{}),form=useForm({order_number:'',access_code:'',turnstile_token:''});const submit=()=>form.post('/orders/check',{onFinish:()=>turnstile.value?.reset()});
</script><template><Head title="Cek pesanan"/><CustomerShell compact-footer><main class="lf-auth-wrap"><form class="lf-auth-card" @submit.prevent="submit"><p class="lf-eyebrow">Transaksi</p><h1>Cek pesanan</h1><p>Masukkan nomor pesanan dan kode akses yang diberikan saat checkout.</p><div class="grid gap-3"><label class="text-[10px] font-semibold text-white/70">Nomor pesanan<input v-model="form.order_number" required maxlength="80"></label><label class="text-[10px] font-semibold text-white/70">Kode akses<input v-model="form.access_code" required maxlength="64"></label><TurnstileWidget v-if="security.turnstile_required" ref="turnstile" :site-key="security.turnstile_site_key" :action="security.turnstile_action" @token="form.turnstile_token=$event"/><button class="lf-primary w-full" :disabled="form.processing">Periksa</button></div><div class="lf-auth-links"><Link href="/">← Beranda</Link><Link href="/login">Masuk akun</Link></div></form></main></CustomerShell></template>